/**
 * §5.8 — the guides Circl writes.
 *
 * The thing worth testing here is not that a row gets written. It is that a staff guide is
 * authored as **Circl's** rather than as the staff member's, that it is a draft until somebody
 * publishes it, that publishing records who stood behind it, and that an auto-generated one goes
 * through the provenance rules rather than around them.
 */
const {
  adminHeaders,
  api,
  check,
  fail,
  finish,
  makeAdmin,
  makeUser,
  prisma,
  sweep,
} = require('./harness.cjs');

const heading = title => console.log(`\n── ${title} ${'─'.repeat(Math.max(0, 58 - title.length))}`);

const body = (extra = {}) => ({
  topicCode: 'MONEY_BANKING',
  title: 'Opening a UK bank account without a credit history',
  intro:
    'Most banks will open an account for you with a passport and a letter. This walks through ' +
    'which documents actually work and what to do when a branch turns you away.',
  blocks: [
    { type: 'HEADING', text: 'What you need' },
    { type: 'PARAGRAPH', text: 'A passport or BRP, and proof of address. A tenancy counts.' },
    {
      type: 'STEP',
      text: 'Book an appointment rather than walking in. Branches turn walk-ins away.',
    },
  ],
  ...extra,
});

async function main() {
  await sweep('pre-run');

  const editor = await makeAdmin('guide-editor', 'manager');
  const reader = await makeAdmin('guide-reader', 'support');
  const headers = adminHeaders(editor);
  const key = () => ({ 'Idempotency-Key': `ag-${Math.random().toString(36).slice(2)}` });

  // ── 1. Authoring ─────────────────────────────────────────────────────────
  heading('1. a guide Circl wrote, not a staff member');

  const topics = await prisma.taxonomyTerm.findMany({
    where: { kind: 'GUIDE_TOPIC', isActive: true },
    select: { code: true },
    take: 1,
  });
  const topicCode = topics[0]?.code ?? 'MONEY_BANKING';

  const created = await api(null, 'POST', '/admin/guides', body({ topicCode }), {
    ...headers,
    ...key(),
  });

  check('the guide is created', created.status === 201, created.body?.error ?? created.status);

  const guideId = created.body?.data?.id;
  const row = guideId
    ? await prisma.guide.findUnique({
        where: { id: guideId },
        select: { authorId: true, publishedAt: true, readTimeMinutes: true, isAutoGenerated: true },
      })
    : null;

  // The author is **null**, not the staff member. A staff id here would publish an employee's name
  // and profile to the whole community.
  check(
    'authored by Circl, with no staff member named on it',
    row?.authorId === null,
    row?.authorId,
  );
  check(
    'and it is a draft — publishing is a separate decision',
    row?.publishedAt === null && created.body?.data?.publishedAt === null,
    { row: row?.publishedAt, view: created.body?.data?.publishedAt },
  );
  check(
    'the read time is computed from the body rather than taken on trust',
    (row?.readTimeMinutes ?? 0) >= 1,
    row?.readTimeMinutes,
  );

  const scanned = await prisma.contentSafety.findUnique({
    where: { targetType_targetId: { targetType: 'GUIDE', targetId: guideId } },
    select: { scanStatus: true, tier: true },
  });

  // Staff copy is the copy nobody else will check, so it goes through the same scan.
  check('a staff guide is scanned like anything else', !!scanned, scanned);

  const badTopic = await api(null, 'POST', '/admin/guides', body({ topicCode: 'NOT_A_TOPIC' }), {
    ...headers,
    ...key(),
  });

  check('an unknown topic is refused', badTopic.status === 422 || badTopic.status === 400, {
    status: badTopic.status,
    code: badTopic.body?.error?.code,
  });

  const httpLink = await api(
    null,
    'POST',
    '/admin/guides',
    body({ topicCode, resourceUrl: 'http://example.com/guide' }),
    { ...headers, ...key() },
  );

  // A guide is published in Circl's name, and an http link in one is a downgrade attack with our
  // name on it.
  check(
    'an http resource link is refused — https only',
    httpLink.status === 422 || httpLink.status === 400,
    { status: httpLink.status, code: httpLink.body?.error?.code },
  );

  // ── 2. Editing ───────────────────────────────────────────────────────────
  heading('2. an edit re-scans, because the words changed');

  const beforeScans = await prisma.contentScan.count({
    where: { contentSafety: { targetType: 'GUIDE', targetId: guideId } },
  });

  const edited = await api(
    null,
    'PATCH',
    `/admin/guides/${guideId}`,
    { title: 'Opening a UK bank account with no credit history' },
    { ...headers, ...key() },
  );

  check('the edit lands', edited.status === 200, edited.body?.error ?? edited.status);
  check(
    'the title changed',
    edited.body?.data?.title === 'Opening a UK bank account with no credit history',
    edited.body?.data?.title,
  );

  const afterScans = await prisma.contentScan.count({
    where: { contentSafety: { targetType: 'GUIDE', targetId: guideId } },
  });

  check('and it was re-scanned', afterScans > beforeScans, {
    before: beforeScans,
    after: afterScans,
  });

  const blocksReplaced = await api(
    null,
    'PATCH',
    `/admin/guides/${guideId}`,
    { blocks: [{ type: 'PARAGRAPH', text: 'One block now, replacing all three.' }] },
    { ...headers, ...key() },
  );

  check(
    'sending blocks replaces the whole list rather than appending',
    (blocksReplaced.body?.data?.blocks ?? []).length === 1,
    blocksReplaced.body?.data?.blocks,
  );

  const tooLong = await api(
    null,
    'PATCH',
    `/admin/guides/${guideId}`,
    { title: 'x'.repeat(141) },
    { ...headers, ...key() },
  );

  // The patch declares its own validators rather than inheriting them loosely: an edit must not be
  // able to write a title no create could. **400**, not 422: a class-validator failure is a 400
  // here and 422 is what the service's own `assertReasoned` returns. Two layers, two codes, and
  // asserting the wrong one was my mistake rather than the API's.
  check(
    'a patch cannot write a title longer than create allows',
    tooLong.status === 400 && tooLong.body?.error?.code === 'VALIDATION_FAILED',
    { status: tooLong.status, code: tooLong.body?.error?.code },
  );

  // ── 3. Publishing ────────────────────────────────────────────────────────
  heading('3. publishing records who stood behind it');

  const published = await api(
    null,
    'POST',
    `/admin/guides/${guideId}/publish`,
    {},
    { ...headers, ...key() },
  );

  check('the publish lands', published.status === 200, published.body?.error ?? published.status);

  const live = await prisma.guide.findUnique({
    where: { id: guideId },
    select: { publishedAt: true, reviewedAt: true, reviewedById: true },
  });

  check('it is published', !!live?.publishedAt, live?.publishedAt);
  check(
    'and the review is attributed — a review nobody is answerable for is the state §1.6.2 prevents',
    !!live?.reviewedAt && live?.reviewedById === editor.id,
    { reviewedAt: live?.reviewedAt, reviewedById: live?.reviewedById },
  );
  check(
    'the response names the reviewer',
    published.body?.data?.reviewedBy?.id === editor.id,
    published.body?.data?.reviewedBy,
  );

  const twice = await api(
    null,
    'POST',
    `/admin/guides/${guideId}/publish`,
    {},
    { ...headers, ...key() },
  );

  check(
    'publishing it twice is a 409 rather than a second review stamp',
    twice.status === 409 && twice.body?.error?.code === 'INVALID_TRANSITION',
    { status: twice.status, code: twice.body?.error?.code },
  );

  // A member can now find it.
  const member = await makeUser('guide-member');
  const memberView = await api(member.token, 'GET', `/community/guides/${guideId}`);

  check('and a member can read it', memberView.status === 200, memberView.status);
  check(
    'with no staff member shown as its author',
    !memberView.body?.data?.author?.id,
    memberView.body?.data?.author,
  );

  // ── 4. Unpublishing ──────────────────────────────────────────────────────
  heading('4. unpublishing keeps the review on the record');

  const pulled = await api(
    null,
    'POST',
    `/admin/guides/${guideId}/unpublish`,
    { reasonCode: 'CORRECTION', note: 'The bank changed its documents list.' },
    { ...headers, ...key() },
  );

  check('the unpublish lands', pulled.status === 200, pulled.body?.error ?? pulled.status);

  const pulledRow = await prisma.guide.findUnique({
    where: { id: guideId },
    select: { publishedAt: true, reviewedAt: true, reviewedById: true },
  });

  check('it is out of the feed', pulledRow?.publishedAt === null, pulledRow?.publishedAt);
  // Clearing the review would make the next publish look like the first.
  check(
    'but somebody still read it, and the record says so',
    !!pulledRow?.reviewedAt && pulledRow?.reviewedById === editor.id,
    pulledRow,
  );

  const unpublishAgain = await api(
    null,
    'POST',
    `/admin/guides/${guideId}/unpublish`,
    { reasonCode: 'CORRECTION', note: 'Again.' },
    { ...headers, ...key() },
  );

  check('unpublishing a draft is a 409', unpublishAgain.status === 409, unpublishAgain.status);

  const noReason = await api(
    null,
    'POST',
    `/admin/guides/${guideId}/unpublish`,
    {},
    { ...headers, ...key() },
  );

  check('and it needs a reason', noReason.status === 422, noReason.status);

  // ── 5. Performance ───────────────────────────────────────────────────────
  heading('5. whether it was worth writing');

  const perf = await api(null, 'GET', `/admin/guides/${guideId}/performance`, null, headers);
  const numbers = perf.body?.data;

  check('performance answers', perf.status === 200, perf.body?.error ?? perf.status);
  check(
    'with every figure §5.8 asks for',
    numbers &&
      [
        'reads',
        'uniqueReaders',
        'completions',
        'likes',
        'bookmarks',
        'usefulYes',
        'usefulNo',
      ].every(field => typeof numbers[field] === 'number'),
    Object.keys(numbers ?? {}),
  );
  check(
    'deflections carry both outcomes',
    typeof numbers?.deflections?.answered === 'number' &&
      typeof numbers?.deflections?.postedAnyway === 'number',
    numbers?.deflections,
  );
  // 0% reads as "it never helps anybody"; "we have not asked" is a different claim.
  check(
    'and a null rate when the interstitial has never been shown',
    numbers?.deflections?.answered + numbers?.deflections?.postedAnyway === 0
      ? numbers?.deflections?.rate === null
      : typeof numbers?.deflections?.rate === 'number',
    numbers?.deflections,
  );
  check(
    'the series carries every day in the window, zeroes included',
    Array.isArray(numbers?.series) && numbers.series.length >= 29 && numbers.series.length <= 31,
    numbers?.series?.length,
  );
  check(
    'each point is a date and a count',
    (numbers?.series ?? []).every(
      point => /^\d{4}-\d{2}-\d{2}$/.test(point.date) && typeof point.reads === 'number',
    ),
    (numbers?.series ?? [])[0],
  );

  // A guide with real reads, to prove the series is not always zero.
  const readGuide = await prisma.guide.findFirst({
    where: { deletedAt: null, publishedAt: { not: null } },
    select: { id: true },
  });
  const reads = await prisma.activityEvent.count({
    where: { subject: 'GUIDE', subjectId: readGuide?.id, verb: 'VIEW' },
  });
  const realPerf = await api(
    null,
    'GET',
    `/admin/guides/${readGuide?.id}/performance?from=${encodeURIComponent(new Date(Date.now() - 400 * 86400000).toISOString())}`,
    null,
    headers,
  );

  check(
    'a guide with real view events reports them, so the series is not decorative',
    reads === 0 || realPerf.body?.data?.reads > 0,
    { eventsInDb: reads, reported: realPerf.body?.data?.reads },
  );

  // ── 6. An auto-generated guide goes through the provenance rules ─────────
  heading('6. a machine-drafted guide is not published bare');

  // Created here rather than looked for: the dataset holds no auto-generated guides, so a version
  // of this that skipped when it found none was a section that never ran.
  const auto = await prisma.guide.create({
    data: {
      title: 'An e2e auto-drafted guide with something behind it',
      intro: 'Drafted from answered questions, with its sources recorded.',
      topicCode,
      isAutoGenerated: true,
      blocks: [],
      sources: {
        create: [{ type: 'REQUEST', refId: 'e2e-guide-source', label: 'An answered question' }],
      },
    },
    select: { id: true },
  });
  const sourceless = await prisma.guide.create({
    data: {
      title: 'An e2e auto-drafted guide with nothing behind it',
      intro: 'No sources, so it may never be published.',
      topicCode,
      isAutoGenerated: true,
      blocks: [],
    },
    select: { id: true },
  });

  await prisma.moderationQueueItem.create({
    data: {
      type: 'AUTO_GUIDE',
      targetType: 'GUIDE',
      targetId: auto.id,
      summary: 'An e2e auto-drafted guide',
      priority: 'NORMAL',
      dueAt: new Date(Date.now() + 24 * 3_600_000),
    },
  });

  const autoPublished = await api(
    null,
    'POST',
    `/admin/guides/${auto.id}/publish`,
    {},
    { ...headers, ...key() },
  );
  const autoRow = await prisma.guide.findUnique({
    where: { id: auto.id },
    select: { publishedAt: true, reviewedById: true },
  });

  check(
    'an auto-guide publishes through AutoGuideService, which owns the provenance rules',
    autoPublished.status === 200 && !!autoRow?.publishedAt,
    { status: autoPublished.status, error: autoPublished.body?.error, row: autoRow },
  );
  check(
    'and its AUTO_GUIDE queue item is resolved, not left for somebody to find already done',
    (await prisma.moderationQueueItem.count({
      where: { type: 'AUTO_GUIDE', targetId: auto.id, decidedAt: null },
    })) === 0,
  );

  // §1.8: a machine-drafted guide with no sources is never published, whoever asks. This is the
  // whole reason publishing routes through `AutoGuideService` rather than stamping `publishedAt`.
  const bare = await api(
    null,
    'POST',
    `/admin/guides/${sourceless.id}/publish`,
    {},
    { ...headers, ...key() },
  );
  const bareRow = await prisma.guide.findUnique({
    where: { id: sourceless.id },
    select: { publishedAt: true },
  });

  check(
    'one with no sources is refused rather than published bare',
    bare.status >= 400 && bareRow?.publishedAt === null,
    { status: bare.status, error: bare.body?.error?.code, publishedAt: bareRow?.publishedAt },
  );

  await prisma.guideSource.deleteMany({ where: { guideId: { in: [auto.id, sourceless.id] } } });
  await prisma.moderationQueueItem.deleteMany({
    where: { targetId: { in: [auto.id, sourceless.id] } },
  });
  await prisma.guide.deleteMany({ where: { id: { in: [auto.id, sourceless.id] } } });

  // ── 7. The guard stack ───────────────────────────────────────────────────
  heading('7. the guard stack');

  const noToken = await api(null, 'GET', `/admin/guides/${guideId}`);

  check('no token, no guide', noToken.status === 401, noToken.status);

  const supportRead = await api(
    null,
    'GET',
    `/admin/guides/${guideId}`,
    null,
    adminHeaders(reader),
  );

  check(
    'support can read the editor, because content:read opens it',
    supportRead.status === 200,
    supportRead.status,
  );

  const supportWrite = await api(null, 'POST', '/admin/guides', body({ topicCode }), {
    ...adminHeaders(reader),
    ...key(),
  });

  // Publishing a guide is publishing in Circl's own name, so it is a narrower grant than reading.
  check(
    'but cannot write one — guides:publish is manager, super admin and trust & safety',
    supportWrite.status === 403,
    supportWrite.status || supportWrite.body?.error,
  );

  await prisma.guide.deleteMany({ where: { id: guideId } });
  await sweep('admin-guides');
  await finish();
}

main().catch(fail);
